def gen(rng):
    def fmt(s):
        return str(len(s)) + ('\n' + s if s else '')
    def balanced(pairs):
        out, opn, left = [], 0, pairs
        total = 2 * pairs
        for _ in range(total):
            if left > 0 and (opn == 0 or rng.random() < 0.5):
                out.append('('); opn += 1; left -= 1
            else:
                out.append(')'); opn -= 1
        return ''.join(out)
    def corrupt(s, k):
        s = list(s)
        for _ in range(k):
            i = rng.randrange(len(s))
            s[i] = '(' if s[i] == ')' else ')'
        return ''.join(s)
    tests = [fmt(''), fmt('('), fmt(')'), fmt('()'), fmt(')('), fmt('(()'), fmt('())'), fmt(')()())'), fmt('()(()))))')]
    for n in (2, 3, 4, 6, 8, 10, 14, 20, 30):
        for _ in range(3):
            p = rng.choice([0.3, 0.5, 0.7])
            tests.append(fmt(''.join('(' if rng.random() < p else ')' for _ in range(n))))
    for pairs in (3, 6, 10, 15):
        tests.append(fmt(balanced(pairs)))
        tests.append(fmt(corrupt(balanced(pairs), 2)))
    N = 100000
    tests.append(fmt('()' * (N // 2)))
    tests.append(fmt('(' * (N // 2) + ')' * (N // 2)))
    tests.append(fmt(''.join('(' if rng.random() < 0.5 else ')' for _ in range(N))))
    tests.append(fmt(corrupt(balanced(N // 2), 20)))
    return tests
